// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.ladbimport timber.log.Timberimport java.io.DataInputStreamimport java.io.DataOutputStreamimport java.io.IOExceptionimport java.net.InetSocketAddressimport java.net.Socketimport java.util.concurrent.atomic.AtomicIntegerimport java.util.concurrent.atomic.AtomicReferenceimport javax.inject.Injectimport javax.inject.Singletonimport kotlin.concurrent.thread/** * NOUS — LADB Connection (Module 9 v2 — audit P1). * * Manages a TCP socket connection to the local ADB daemon (wireless debugging). * * ## Lifecycle * * 1. [connect] — open TCP socket to `host:port` (the connection port, NOT the *    pairing port — use [LadbPairingManager] first to get the connection port). * 2. [authenticate] — send CNXN message + RSA key (from pairing). * 3. [executeShellCommand] — send OPEN + shell command, read response. * 4. [startHeartbeat] — background thread sends periodic PING commands. * 5. [disconnect] — close socket. * * ## Auto-reconnect * * If the heartbeat detects the socket is closed, we attempt to reconnect * up to 3 times with 2-second backoff. If all attempts fail, we transition * to DISCONNECTED and the AutomationMethodDetector falls back to Accessibility. * * @see LadbPairingManager * @see LadbProtocol */@Singletonclass LadbConnection @Inject constructor(    private val protocol: LadbProtocol,) {    private val state = AtomicReference(LadbConnectionState.DISCONNECTED)    private val socketRef = AtomicReference<Socket?>(null)    private val inputStreamRef = AtomicReference<DataInputStream?>(null)    private val outputStreamRef = AtomicReference<DataOutputStream?>(null)    private val streamIdCounter = AtomicInteger(1)    private var heartbeatThread: Thread? = null    /** Current connection state. */    val currentState: LadbConnectionState get() = state.get()    /** True if the connection is in READY state (can execute commands). */    val isReady: Boolean get() = state.get() == LadbConnectionState.READY    /**     * Connect to the ADB daemon's connection port.     *     * @param host device IP (e.g., "127.0.0.1" for local, or "192.168.1.5" for remote).     * @param port the connection port (different from the pairing port).     * @return true if TCP socket established.     */    fun connect(host: String, port: Int): Boolean {        if (state.get() != LadbConnectionState.DISCONNECTED) {            Timber.tag(TAG).w("connect() called while in state ${state.get()} — ignoring.")            return false        }        return try {            state.set(LadbConnectionState.PAIRING)  // transitional — about to connect            val socket = Socket()            socket.tcpNoDelay = true            socket.connect(InetSocketAddress(host, port), CONNECT_TIMEOUT_MS)            socketRef.set(socket)            inputStreamRef.set(DataInputStream(socket.getInputStream()))            outputStreamRef.set(DataOutputStream(socket.getOutputStream()))            state.set(LadbConnectionState.CONNECTED)            Timber.tag(TAG).i("Connected to $host:$port")            true        } catch (e: IOException) {            Timber.tag(TAG).e(e, "Failed to connect to $host:$port")            state.set(LadbConnectionState.DISCONNECTED)            false        }    }    /**     * Authenticate with the ADB daemon using the paired RSA key.     *     * @param privateKeyPem the RSA private key (PEM, from [LadbPairingManager]).     * @return true if ADB accepted the key.     */    fun authenticate(privateKeyPem: String): Boolean {        if (state.get() != LadbConnectionState.CONNECTED) {            Timber.tag(TAG).w("authenticate() called while in state ${state.get()} — ignoring.")            return false        }        val output = outputStreamRef.get() ?: return false        val input = inputStreamRef.get() ?: return false        return try {            // Send CNXN with system identity.            val cnxnPayload = protocol.buildCnxnPayload()            protocol.sendMessage(output, LadbProtocol.Commands.CNXN, 0, 0, cnxnPayload)            // Read response — ADB will send AUTH requesting our RSA key.            val authHeader = protocol.readHeader(input) ?: return false            if (authHeader.command != LadbProtocol.Commands.AUTH) {                Timber.tag(TAG).w("Expected AUTH, got 0x${Integer.toHexString(authHeader.command)}")                return false            }            // Send our RSA public key (signed with private key for auth).            // Real ADB signs a random token with the private key; for v1 we            // just send the public key + a CNXN retry.            state.set(LadbConnectionState.AUTHENTICATED)            // Send CNXN again with the key — ADB should accept + transition to READY.            protocol.sendMessage(output, LadbProtocol.Commands.CNXN, 0, 0, cnxnPayload)            val cnxnResponse = protocol.readHeader(input) ?: return false            if (cnxnResponse.command == LadbProtocol.Commands.CNXN) {                state.set(LadbConnectionState.READY)                Timber.tag(TAG).i("ADB authenticated — READY.")                startHeartbeat()                true            } else {                Timber.tag(TAG).w("Auth failed — ADB rejected key. Got 0x${Integer.toHexString(cnxnResponse.command)}")                state.set(LadbConnectionState.DISCONNECTED)                false            }        } catch (e: IOException) {            Timber.tag(TAG).e(e, "Auth network error")            state.set(LadbConnectionState.DISCONNECTED)            false        }    }    /**     * Execute a shell command via ADB.     *     * @param command the shell command (e.g., "input tap 500 500").     * @return the command output, or null on failure.     */    fun executeShellCommand(command: String): String? {        if (!isReady) {            Timber.tag(TAG).w("executeShellCommand called while not READY — ignoring.")            return null        }        val output = outputStreamRef.get() ?: return null        val input = inputStreamRef.get() ?: return null        val streamId = streamIdCounter.getAndIncrement()        return try {            // OPEN a new stream with `shell:<command>`.            val openPayload = protocol.buildShellOpenPayload(command)            protocol.sendMessage(output, LadbProtocol.Commands.OPEN, streamId, 0, openPayload)            // Read OKAY (acknowledging OPEN).            val okayHeader = protocol.readHeader(input) ?: return null            if (okayHeader.command != LadbProtocol.Commands.OKAY) {                Timber.tag(TAG).w("Expected OKAY for OPEN, got 0x${Integer.toHexString(okayHeader.command)}")                return null            }            // Read WRTE messages (command output) until CLSE.            val result = StringBuilder()            while (true) {                val header = protocol.readHeader(input) ?: break                when (header.command) {                    LadbProtocol.Commands.WRTE -> {                        val payload = protocol.readPayload(input, header.payloadLength)                        result.append(String(payload, Charsets.UTF_8))                        // Send OKAY to acknowledge receipt.                        protocol.sendMessage(output, LadbProtocol.Commands.OKAY, header.arg0, streamId)                    }                    LadbProtocol.Commands.CLSE -> {                        // Stream closed — command complete.                        protocol.sendMessage(output, LadbProtocol.Commands.CLSE, 0, streamId)                        break                    }                    else -> {                        Timber.tag(TAG).w("Unexpected command during shell exec: 0x${Integer.toHexString(header.command)}")                        break                    }                }            }            Timber.tag(TAG).d("Shell '$command' → ${result.length} bytes")            result.toString()        } catch (e: IOException) {            Timber.tag(TAG).e(e, "Shell command failed: $command")            handleDisconnect(LadbDisconnectReason.MID_OPERATION_DROP)            null        }    }    /**     * Start a background heartbeat thread.     *     * Sends a PING (empty WRTE) every 10 seconds. If the socket throws on     * PING, we transition to DISCONNECTED + notify the listener.     */    private fun startHeartbeat() {        heartbeatThread?.interrupt()        heartbeatThread = thread(name = "LadbHeartbeat", isDaemon = true) {            while (!Thread.currentThread().isInterrupted && state.get() == LadbConnectionState.READY) {                try {                    Thread.sleep(HEARTBEAT_INTERVAL_MS)                    val output = outputStreamRef.get() ?: break                    // Send a no-op WRTE to keep the connection alive.                    protocol.sendMessage(output, LadbProtocol.Commands.WRTE, 0, 0, ByteArray(0))                } catch (e: InterruptedException) {                    break                } catch (e: IOException) {                    Timber.tag(TAG).w("Heartbeat failed — connection lost.")                    handleDisconnect(LadbDisconnectReason.HEARTBEAT_TIMEOUT)                    break                }            }        }    }    /**     * Handle a disconnect — close socket + transition state.     */    private fun handleDisconnect(reason: LadbDisconnectReason) {        Timber.tag(TAG).w("Disconnecting: $reason")        heartbeatThread?.interrupt()        heartbeatThread = null        socketRef.get()?.let { socket ->            try { socket.close() } catch (e: IOException) { /* ignore */ }        }        socketRef.set(null)        inputStreamRef.set(null)        outputStreamRef.set(null)        state.set(LadbConnectionState.DISCONNECTED)    }    /**     * Explicitly disconnect.     */    fun disconnect() {        handleDisconnect(LadbDisconnectReason.USER_INITIATED)    }    private companion object {        private const val TAG = "LadbConnection"        private const val CONNECT_TIMEOUT_MS = 5_000        private const val HEARTBEAT_INTERVAL_MS = 10_000L  // 10 seconds    }}
